new='''/** Holds retired at or after this instant are still in force. */
function holdCutoff(now: Date = new Date()): string {
  return toIsoTimestamp(
    new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000),
  );
}

/**
 * Resolves a slug to its live org: the current slug first, then a slug the
 * org retired by renaming while its hold lasts (ADR 0005).
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const held = db
    .select({ org: organizations })
    .from(organizationSlugHolds)
    .innerJoin(organizations, eq(organizations.id, organizationSlugHolds.orgId))
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return held ? toOrganization(held.org) : null;
}

/**
 * Whether `slug` may become `orgId`'s slug: no other org (live or archived)
 * holds it as its current slug, and no other org holds it retired.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const db = getDb();
  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const held = db
    .select({ orgId: organizationSlugHolds.orgId })
    .from(organizationSlugHolds)
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        ne(organizationSlugHolds.orgId, orgId),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
      ),
    )
    .get();
  return !held;
}

/**
 * Moves `orgId` to `slug`, retiring its current slug and ending any hold the
 * org itself had on `slug`. Runs in one transaction.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  const db = getDb();
  return db.transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const stamp = toIsoTimestamp(new Date());

    tx.delete(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, slug))
      .run();
    tx.insert(organizationSlugHolds)
      .values({ slug: current.slug, orgId, retiredAt: stamp })
      .onConflictDoUpdate({
        target: organizationSlugHolds.slug,
        set: { orgId, retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    return toOrganization(row);
  });
}'''
