 * holds it as its current slug, and no other org holds it retired.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const db = getDb();
  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
